```{.python .cell-code}
from econml.dr import DRLearner

dr_learner = DRLearner(
    model_propensity=HistGradientBoostingClassifier(
        learning_rate=0.05,
        max_iter=150,
        max_leaf_nodes=15,
        min_samples_leaf=30,
        l2_regularization=1.0,
        random_state=123,
    ),
    model_regression=HistGradientBoostingClassifier(
        learning_rate=0.05,
        max_iter=200,
        max_leaf_nodes=15,
        min_samples_leaf=30,
        l2_regularization=1.0,
        random_state=123,
    ),
    model_final=HistGradientBoostingRegressor(
        learning_rate=0.05,
        max_iter=200,
        max_leaf_nodes=15,
        min_samples_leaf=30,
        l2_regularization=1.0,
        random_state=123,
    ),
    discrete_outcome=True,
    min_propensity=0.01,
    cv=5,
    random_state=123,
)

# nuisance modelはcv=5でcross-fittingされる
dr_learner.fit(Y_train, T_train, X=X_train)
